           // Einheit: deg (Gradma\xdf 0 ... 360\xb0)\n\nvoid setup(){\n    Serial.begin(115200);\n\n    lcd.clear(); lcd.print("Gyro Cal");\n    lcd.gotoXY(0, 1); lcd.print("ibration");\n\n    Wire.begin();\n    imu.init();\n    imu.configureForTurnSensing();        // Empfindlichkeit und Filter einstellen\n\n    // Ermitteln des Offset-Fehlers des Gyroskops\n    float sumGyro = 0;\n    for (long i = 0 ; i < 2000; i++) {\n        while (!imu.gyroDataReady()) {}   // Warten auf neue Gyro-Daten\n        imu.readGyro();                   // Einlesen der Gyro-Daten\n        sumGyro += imu.g.z;               // imu.g.z: Winkelgeschwindigkeit der z-Achse in mdps/digit\n    }\n    offSet = sumGyro / 2000;              // Offset-Fehler berechnen\n\n    gyroLastUpdate = micros();\n    lcd.clear();  lcd.print("Winkel:");\n}\n\nvoid loop()\n{\n    unsigned long now = micros();         // Zeit in Mikrosekunden (\xb5s)\n    long dt = now - gyroLastUpdate;       // Zeitdifferenz in Mikrosekunden (\xb5s)\n    gyroLastUpdate = now;\n\n    float drehRate, deltaWinkel;\n    imu.readGyro();                       // Einlesen der Gyro-Daten\n    drehRate = (imu.g.z - offSet) * 0.07; // Winkelgeschwindigkeit umgerechnet in deg/s (Gradma\xdf/Sekunde)\n    deltaWinkel = drehRate * dt / 1e6;    // Winkel\xe4nderung pro Zeitintervall (dt in Sekunden umrechnen)\n    winkel += deltaWinkel;                // Drehwinkel als Summe aller Winkel\xe4nderung\n\n    if (millis() - lastTime > 200) {\n        lastTime = millis();\n        lcd.gotoXY(0, 1); lcd.print(winkel ); lcd.print("   ");\n    }\n}\n'})})]})}function u(e={}){const{wrapper:n}={...(0,l.R)(),...e.components};return n?(0,d.jsx)(n,{...e,children:(0,d.jsx)(c,{...e})}):c(e)}},8453(e,n,i){i.d(n,{R:()=>s,x:()=>o});var r=i(6540);const d={},l=r.createContext(d);function s(e){const n=r.useContext(l);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==t